import React, { useState } from 'react';
import { View, Text, StyleSheet, ScrollView, TouchableOpacity, ImageBackground, Image } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { MaterialCommunityIcons, Ionicons } from '@expo/vector-icons';
import { Images } from '../data';

export default function PoojaTab() {
  const [lightsOn, setLightsOn] = useState(false);
  const [incenseOn, setIncenseOn] = useState(false);

  const toggleLights = () => setLightsOn(!lightsOn);
  const toggleIncense = () => setIncenseOn(!incenseOn);

  return (
    <ImageBackground
      source={Images["ramSita_1"]}
      style={styles.backgroundImage}
      resizeMode="cover"
    >
      <SafeAreaView style={styles.container}>
        <View style={styles.overlayContainer}>
          <Text style={styles.title}>Virtual Pooja Room</Text>

          <ScrollView style={styles.content} showsVerticalScrollIndicator={false}>
            {/* Deity Section */}
            <View style={styles.deitySection}>
              <View style={styles.deityContainer}>
                <Image 
                  source={Images["ram_1"]} 
                  style={styles.deityImage}
                  resizeMode="contain"
                />
              </View>
            </View>

            {/* Offerings Section */}
            <View style={styles.offeringsSection}>
              <Text style={styles.sectionTitle}>Sacred Offerings</Text>

              <View style={styles.offeringsGrid}>
                <TouchableOpacity 
                  style={[styles.offeringItem, lightsOn && styles.activeOffering]}
                  onPress={toggleLights}
                >
                  <MaterialCommunityIcons 
                    name={lightsOn ? "candle" : "candle"} 
                    size={32} 
                    color={lightsOn ? "#f59e0b" : "#9ca3af"} 
                  />
                  <Text style={styles.offeringText}>Diya</Text>
                </TouchableOpacity>

                <TouchableOpacity 
                  style={[styles.offeringItem, incenseOn && styles.activeOffering]}
                  onPress={toggleIncense}
                >
                  <MaterialCommunityIcons 
                    name="smoke" 
                    size={32} 
                    color={incenseOn ? "#f59e0b" : "#9ca3af"} 
                  />
                  <Text style={styles.offeringText}>Incense</Text>
                </TouchableOpacity>

                <TouchableOpacity style={styles.offeringItem}>
                  <MaterialCommunityIcons name="flower" size={32} color="#9ca3af" />
                  <Text style={styles.offeringText}>Flowers</Text>
                </TouchableOpacity>

                <TouchableOpacity style={styles.offeringItem}>
                  <Ionicons name="water" size={32} color="#9ca3af" />
                  <Text style={styles.offeringText}>Water</Text>
                </TouchableOpacity>
              </View>
            </View>

            {/* Aarti Section */}
            <View style={styles.aartiSection}>
              <Text style={styles.sectionTitle}>Aarti</Text>
              <TouchableOpacity style={styles.aartiButton}>
                <Ionicons name="play-circle" size={24} color="white" />
                <Text style={styles.aartiButtonText}>Start Aarti</Text>
              </TouchableOpacity>
            </View>

            {/* Prayers Section */}
            <View style={styles.prayersSection}>
              <Text style={styles.sectionTitle}>Quick Prayers</Text>

              <TouchableOpacity style={styles.prayerItem}>
                <Text style={styles.prayerText}>Hanuman Chalisa</Text>
                <Ionicons name="chevron-forward" size={20} color="#f59e0b" />
              </TouchableOpacity>

              <TouchableOpacity style={styles.prayerItem}>
                <Text style={styles.prayerText}>Vishnu Sahasranama</Text>
                <Ionicons name="chevron-forward" size={20} color="#f59e0b" />
              </TouchableOpacity>

              <TouchableOpacity style={styles.prayerItem}>
                <Text style={styles.prayerText}>Gayatri Mantra</Text>
                <Ionicons name="chevron-forward" size={20} color="#f59e0b" />
              </TouchableOpacity>
            </View>
          </ScrollView>
        </View>
      </SafeAreaView>
    </ImageBackground>
  );
}

