import * as Speech from "expo-speech";
import React, { useEffect, useRef, useState } from "react";
import {
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  TouchableOpacity,
  View,
  Image,
  ImageBackground,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { Images, BhagwanScroller } from '../data';

const sampleText = `
श्रीरामचन्द्र कृपालु भजुमन, हरण भवभय दारुणम् ।\n
नव कञ्ज-लोचन कञ्ज मुख कर कञ्ज पद कञ्जारुणम् ॥
`;

export default function ScripturesTab() {
  const scrollRef = useRef(null);
  const [isReading, setIsReading] = useState(false);
  const [autoScroll, setAutoScroll] = useState(false);
  const [showFloatingControls, setShowFloatingControls] = useState(false);

  useEffect(() => {
    if (isReading) {
      Speech.speak(sampleText, {
        onDone: () => setIsReading(false),
        onStopped: () => setIsReading(false),
        language: "hi-IN",
        pitch: 1,
        rate: 0.8,
      });
    } else {
      Speech.stop();
    }
  }, [isReading]);

  const toggleReading = () => {
    setIsReading(!isReading);
  };

  return (
    <ImageBackground
      source={Images["ramSita_1"]}
      style={styles.backgroundImage}
      resizeMode="cover"
    >
      <SafeAreaView style={styles.container}>
        <View style={styles.overlayContainer}>
          <View style={styles.header}>
            <Text style={styles.title}>Scripture Reader</Text>
            <View style={styles.headerControls}>
              <TouchableOpacity
                style={[styles.controlButton, isReading && styles.activeButton]}
                onPress={toggleReading}
              >
                <Text style={styles.controlButtonText}>
                  {isReading ? "⏸️" : "▶️"}
                </Text>
              </TouchableOpacity>
            </View>
          </View>

          <ScrollView
            ref={scrollRef}
            style={styles.textContainer}
            contentContainerStyle={styles.textContent}
          >
            <Text style={styles.scriptureText}>{sampleText}</Text>
          </ScrollView>

          <View style={styles.bottomControls}>
            <View style={styles.switchContainer}>
              <Text style={styles.switchLabel}>Auto Scroll</Text>
              <Switch
                value={autoScroll}
                onValueChange={setAutoScroll}
                trackColor={{ false: "#767577", true: "#f59e0b" }}
                thumbColor={autoScroll ? "#ffffff" : "#f4f3f4"}
              />
            </View>
          </View>
        </View>
      </SafeAreaView>
