import BottomNavigation from "../../../../components/BottomNavigation";
import { Images, BhagwanScroller } from '../../../data';

const TouchableOpacity = (props: any) => (
    <RNTouchableOpacity activeOpacity={0.7} {...props} />
);

// Scripture categories
const scriptures = [
    { name: 'Ramayana', icon: 'book-open' },
    { name: 'Bhagavad Gita', icon: 'book' },
    { name: 'Shiv Puran', icon: 'book-reader' },
    { name: 'Vishnu Puran', icon: 'scroll' },
    { name: 'Durga Saptashati', icon: 'file-alt' },
    { name: 'Hanuman Chalisa', icon: 'bookmark' },
];

const ScriptureCategoryScreen = () => {
    const router = useRouter();

    const handlePress = (category: string) => {
        router.push({
            pathname: '/screens/scripture/scripture-chapter',
            params: { category: category }
        });
    };

    return (
        <View style={styles.container}>
            <ImageBackground
                source={Images.deity.vishnu.vishnu_1}
                style={styles.backgroundImage}
                resizeMode="cover"
            >
                <ScrollView contentContainerStyle={styles.overlayContainer}>
                    <Breadcrumb
                        items={[
                            { label: 'Home', path: '/' },
                            { label: 'Scripture Categories' }
                        ]}
                    />
                    <View style={styles.innerContainer}>
                        {/* Avatar Scroll */}
                        <View style={{ height: 80, marginBottom: 20, width: Dimensions.get('window').width, paddingHorizontal: 6 }}>
                            <ScrollView
                                horizontal
                                showsHorizontalScrollIndicator={false}
                                contentContainerStyle={{ alignItems: 'center' }}
                            >
                                {BhagwanScroller.map((name, idx) => (
                                    <Image
                                        key={idx}
                                        source={Images.icon[name]}
                                        style={{
                                            width: 56,
                                            height: 56,
                                            borderRadius: 28,
                                            borderWidth: 2,
                                            borderColor: '#facc15',
                                            marginHorizontal: 6,
                                        }}
                                    />
                                ))}
                            </ScrollView>
                        </View>

                        {/* Title */}
                        <Text style={styles.title}>Explore Sacred Scriptures</Text>

                        {/* Scripture Buttons */}
                        {scriptures.map((scripture, index) => (
                            <TouchableOpacity
                                key={scripture.name}
                                style={[styles.button, { marginBottom: 12 }]}
                                onPress={() => handlePress(scripture.name)}
                            >
                                <FontAwesome5 name={scripture.icon} size={26} color="white" />
                                <Text style={styles.buttonText}>{scripture.name}</Text>
                            </TouchableOpacity>
                        ))}
                    </View>
                </ScrollView>
            </ImageBackground>
            <BottomNavigation />
        </View>
    );
};

export default ScriptureCategoryScreen;

const styles = StyleSheet.create({
    container: {
        flex: 1,
        backgroundColor: '#1e293b', // bg-slate-800
    },
    innerContainer: {
        alignItems: 'center',
    },
    title: {
        fontSize: 26,
        fontWeight: 'bold',
        color: '#fef08a',
        marginBottom: 20,
    },
    button: {
        backgroundColor: 'rgba(100, 116, 139, 0.4)',
        borderRadius: 16,
        flexDirection: 'row',
        alignItems: 'center',
        padding: 16,
        width: '91%',
        borderWidth: 2,
        borderColor: 'rgba(148, 163, 184, 0.3)',
    },
    buttonText: {
        color: 'white',
        fontSize: 18,
        marginLeft: 16,
    },
    backgroundImage: {
        flex: 1,
        width: Dimensions.get('window').width,
        height: Dimensions.get('window').height,
    },
    overlayContainer: {
        flexGrow: 1,
        backgroundColor: 'rgba(30, 41, 59, 0.3)',
        alignItems: 'center',
        paddingTop: 40,
        paddingBottom: 80,
    },
});

import * as Haptics from 'expo-haptics';
import { ComponentProps } from 'react';
import { TouchableOpacity } from 'react-native';

export function HapticTab(props: ComponentProps<typeof TouchableOpacity>) {
  return (
    <TouchableOpacity
      {...props}
      onPress={(ev) => {
        if (process.env.EXPO_OS === 'ios') {
          // Add a soft haptic feedback when tab is pressed on iOS
          Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
        }
        props.onPress?.(ev);
      }}
    />
  );
}
